import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.Ke88N3OB.js";var c=JSON.parse(`{"title":"Verify Pumpkin plugin signatures","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/actions/verify-pumpkin-plugin/docs/index.md"},"headers":[],"relativePath":"actions/verify-pumpkin-plugin/docs/index.md","filePath":"actions/verify-pumpkin-plugin/docs/index.md","lastUpdated":1792252155000}`),l={name:`actions/verify-pumpkin-plugin/docs/index.md`},u={id:`verify-pumpkin-plugin-signatures`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/verify-pumpkin-plugin-v0.0.5`,"aria-label":`Release v0.0.5`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`span`,{class:`component-page-title__text`},[t(`Verify Pumpkin plugin signatures `),n(`a`,{class:`header-anchor`,href:`#verify-pumpkin-plugin-signatures`,"aria-label":`Permalink to “Verify Pumpkin plugin signatures”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.0.5`})])]),c[1]||=r(`<p>Before you publish, deploy, or accept a Pumpkin plugin as a dependency, use this action to check its <code>.wasm</code> file. The action verifies the Ed25519 signature and the release metadata embedded in the file, and it leaves the file unchanged. Add it after the step that builds or downloads the artifact so an invalid signature or unexpected metadata can stop the workflow before the artifact is used.</p><p>For a workflow example and the full input and output lists, see the <a href="./../README">action README</a>.</p><h2 id="choose-what-to-verify" tabindex="-1">Choose what to verify <a class="header-anchor" href="#choose-what-to-verify" aria-label="Permalink to “Choose what to verify”">​</a></h2><p>For one plugin, provide <code>wasm-file</code>. You can also set <code>plugin-name</code> and <code>version</code> to require exact values in the signed metadata; provide the version without a leading <code>v</code>.</p><p>For several plugins, provide <code>plugins-manifest</code> as a JSON array. Each entry needs <code>plugin-name</code>, <code>version</code>, and <code>wasm-file</code> fields. The action checks each file against the name and version in its signed metadata and reports how many files passed. Set either <code>wasm-file</code> or <code>plugins-manifest</code>, not both.</p><h2 id="decide-which-signer-to-trust" tabindex="-1">Decide which signer to trust <a class="header-anchor" href="#decide-which-signer-to-trust" aria-label="Permalink to “Decide which signer to trust”">​</a></h2><p>Set <code>expected-public-key</code> to pin verification to a public key you obtained through a trusted channel. The action fails if a file was signed with a different key. If you omit this input, the action still checks that each signature matches its file and metadata, but it cannot identify or authenticate the signer.</p><h2 id="read-the-result" tabindex="-1">Read the result <a class="header-anchor" href="#read-the-result" aria-label="Permalink to “Read the result”">​</a></h2><p>The action succeeds only when every selected file has a valid signature and passes the metadata checks. It reports the number of verified files as <code>verified-count</code>. For a single file, it also provides the signed plugin name, version, developer name, public key, and signing timestamp as step outputs.</p>`,9)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};